final List<Map<String, dynamic>> hoerenModels = List<Map<String, dynamic>>.from(json.decode(r'''[{"id":"hoeren-1","title":"نموذج Hören رقم 1","description":"نموذج استماع كامل مع النص المكتوب (Transkript). يُنصح أن تقرأ النص بصوت عالٍ أو تطلب من صديق قراءته لك، وتجيب على الأسئلة بدون النظر إلى النص.","parts":[{"type":"tf-mc","title":"Teil 1 – رسائل قصيرة","instructionsAr":"خمس رسائل قصيرة على هاتفك الصوتي أو من الراديو. لكل رسالة سؤالان: صح/خطأ ثم اختيار من متعدد.","transcripts":[{"id":"h1-1","speaker":"Nachricht 1","textDe":"Hallo Maria, hier ist Tom. Du, wegen unseres Treffens heute Abend: Ich schaffe es leider nicht um 19 Uhr, weil meine Tochter krank ist. Können wir auf 20 Uhr verschieben? Ort bleibt gleich – Café Rosa. Ruf mich bitte zurück. Tschüss!"},{"id":"h1-2","speaker":"Nachricht 2","textDe":"Guten Tag, hier ist die Praxis Dr. Schmidt. Ihr Termin am Freitag um 10:00 Uhr wurde verschoben auf Montag, 13:30 Uhr. Bitte bestätigen Sie den neuen Termin telefonisch unter 030 123456. Vielen Dank."},{"id":"h1-3","speaker":"Verkehrsdurchsage","textDe":"Achtung liebe Fahrgäste, wegen Bauarbeiten fahren die U-Bahnen der Linie U6 heute nur zwischen Friedrichstraße und Alt-Mariendorf. Zwischen Tegel und Friedrichstraße fahren Ersatzbusse. Wir bitten um Ihr Verständnis."},{"id":"h1-4","speaker":"Nachricht 4","textDe":"Hallo Herr Al-Ahmad, Kabir hier vom Fitnessstudio. Ihre Mitgliedschaft endet nächste Woche. Wenn Sie verlängern möchten, bekommen Sie 20 % Rabatt. Bitte kommen Sie einfach an der Rezeption vorbei. Schönen Tag!"},{"id":"h1-5","speaker":"Radiowerbung","textDe":"Elektromarkt „Blitz\"! Nur am Samstag: Fernseher, Waschmaschinen und Handys um bis zu 40 % reduziert. Kommen Sie in die Hauptstraße 15 in Köln und sparen Sie! Nur am Samstag, 9 bis 18 Uhr!"}],"questions":[{"id":"hoeren-1-1-1","statementDe":"Tom kommt heute nicht zum Treffen.","statementAr":"توم لن يأتي إلى اللقاء اليوم.","correct":false,"explanation":"سيأتي لكن متأخراً ساعة واحدة."},{"id":"hoeren-1-1-2","promptDe":"Um wie viel Uhr treffen sich Tom und Maria jetzt?","options":[{"id":"a","de":"Um 19:00 Uhr."},{"id":"b","de":"Um 20:00 Uhr."},{"id":"c","de":"Sie treffen sich nicht."}],"correct":"b"},{"id":"hoeren-1-1-3","statementDe":"Der Termin bei Dr. Schmidt ist auf Montag verschoben.","correct":true},{"id":"hoeren-1-1-4","promptDe":"Wie soll der Patient reagieren?","options":[{"id":"a","de":"Er soll zur Praxis kommen."},{"id":"b","de":"Er soll telefonisch bestätigen."},{"id":"c","de":"Er muss nichts tun."}],"correct":"b"},{"id":"hoeren-1-1-5","statementDe":"Die U6 fährt heute wie immer.","correct":false},{"id":"hoeren-1-1-6","promptDe":"Was fährt zwischen Tegel und Friedrichstraße?","options":[{"id":"a","de":"Taxis."},{"id":"b","de":"Ersatzbusse."},{"id":"c","de":"Gar nichts."}],"correct":"b"},{"id":"hoeren-1-1-7","statementDe":"Herr Al-Ahmad bekommt einen Rabatt beim Fitnessstudio.","correct":true},{"id":"hoeren-1-1-8","statementDe":"Der Elektromarkt hat den ganzen Monat reduziert.","correct":false,"explanation":"فقط يوم السبت."}]},{"type":"match-speakers","title":"Teil 2 – خمسة متحدثين","instructionsAr":"خمسة أشخاص يتحدثون عن \"العمل بدوام جزئي\". اربط كل شخص بالجملة المناسبة. يوجد جملة زائدة.","transcripts":[{"id":"s1","speaker":"Person 1 – Sabrina","textDe":"Ich arbeite jetzt nur noch 20 Stunden pro Woche, weil meine Kinder noch klein sind. Das Gehalt ist weniger, aber ich habe mehr Zeit für die Familie. Für mich ist das perfekt."},{"id":"s2","speaker":"Person 2 – Hamid","textDe":"Teilzeit ist nichts für mich. Ich brauche das Geld und ich arbeite gern. Acht Stunden pro Tag, dazu ein paar Überstunden, das macht mir nichts aus."},{"id":"s3","speaker":"Person 3 – Linda","textDe":"Ich studiere noch und arbeite 10 Stunden in der Woche als Verkäuferin. Nur so kann ich mein Studium finanzieren. Mehr geht nicht, sonst habe ich keine Zeit zum Lernen."},{"id":"s4","speaker":"Person 4 – Karl","textDe":"Seit meiner Krankheit kann ich nicht mehr voll arbeiten. Jetzt bin ich drei Tage im Büro und zwei Tage zu Hause. Mein Chef ist sehr verständnisvoll."},{"id":"s5","speaker":"Person 5 – Meryem","textDe":"Ich habe zwei Teilzeitjobs: morgens in einer Bäckerei und nachmittags als Reinigungskraft. Zusammen verdiene ich genug, aber es ist anstrengend."}],"options":[{"id":"a","titleDe":"Diese Person hat gesundheitliche Probleme.","textDe":""},{"id":"b","titleDe":"Diese Person findet Teilzeit ungeeignet.","textDe":""},{"id":"c","titleDe":"Diese Person hat mehrere kleine Jobs.","textDe":""},{"id":"d","titleDe":"Diese Person arbeitet wegen der Kinder weniger.","textDe":""},{"id":"e","titleDe":"Diese Person arbeitet neben dem Studium.","textDe":""},{"id":"f","titleDe":"Diese Person ist im Ruhestand.","textDe":""}],"questions":[],"matchItems":[{"id":"s1","textDe":"Sabrina","correctAd":"d"},{"id":"s2","textDe":"Hamid","correctAd":"b"},{"id":"s3","textDe":"Linda","correctAd":"e"},{"id":"s4","textDe":"Karl","correctAd":"a"},{"id":"s5","textDe":"Meryem","correctAd":"c"}]},{"type":"tf-dialog","title":"Teil 3 – حوار قصير","instructionsAr":"اقرأ الحوار (أو اطلب من أحدهم قراءته بصوت عال) ثم أجب صح / خطأ.","transcripts":[{"id":"d1","textDe":"A: Guten Tag, hier ist das Rathaus. Wie kann ich Ihnen helfen?\nB: Guten Tag. Mein Name ist Omar Khalil. Ich möchte einen Termin für die Anmeldung meiner Familie.\nA: Ja, einen Moment. Wie groß ist Ihre Familie?\nB: Wir sind vier Personen: meine Frau, zwei Kinder und ich.\nA: Sie brauchen dafür ungefähr 20 Minuten. Haben Sie einen bestimmten Tag?\nB: Am besten nächste Woche, wenn möglich Donnerstag oder Freitag, am Nachmittag.\nA: Ich kann Ihnen Freitag um 14:15 Uhr anbieten.\nB: Das passt gut. Vielen Dank.\nA: Bitte bringen Sie mit: Pässe, Mietvertrag und die Wohnungsgeberbestätigung. Und bitte seien Sie pünktlich.\nB: In Ordnung. Auf Wiederhören."}],"questions":[{"id":"hoeren-1-3-1","statementDe":"Herr Khalil hat zwei Kinder.","correct":true},{"id":"hoeren-1-3-2","statementDe":"Der Termin ist am Donnerstag.","correct":false},{"id":"hoeren-1-3-3","statementDe":"Herr Khalil muss den Mietvertrag mitbringen.","correct":true},{"id":"hoeren-1-3-4","statementDe":"Die Familie braucht ungefähr eine Stunde.","correct":false,"explanation":"حوالي 20 دقيقة."},{"id":"hoeren-1-3-5","statementDe":"Der Termin ist am Nachmittag.","correct":true},{"id":"hoeren-1-3-6","statementDe":"Eine Arbeitsbescheinigung ist nötig.","correct":false}]},{"type":"match-opinions","title":"Teil 4 – نقاش في الراديو","instructionsAr":"نقاش بين شخصين حول \"الطعام النباتي\". لكل جملة قرّر: قالها المتحدث (1)، المتحدثة (2)، أم لم يقلها أحد.","transcripts":[{"id":"r1","textDe":"Moderator: Heute geht es um vegetarisches und veganes Essen. Unsere Gäste sind Herr Wagner (Koch) und Frau Ibrahim (Ernährungsexpertin).\n\nHerr Wagner: Ich kann verstehen, dass viele Menschen weniger Fleisch essen wollen. Aber in meinem Restaurant muss es auch Fleischgerichte geben, sonst kommen die Gäste nicht.\n\nFrau Ibrahim: Das stimmt nicht ganz. Ich kenne viele Restaurants, die nur vegetarisch kochen und voll sind. Gerade in Großstädten wächst die Nachfrage.\n\nHerr Wagner: Ok, aber viele Menschen denken, vegetarisches Essen ist langweilig und schmeckt nicht. Fleisch ist einfacher.\n\nFrau Ibrahim: Das ist ein Vorurteil! Mit Gewürzen und frischem Gemüse schmeckt es wunderbar. Und vegetarisches Essen ist oft gesünder und billiger.\n\nHerr Wagner: Billiger? Da widerspreche ich. Tofu und Soja-Produkte sind manchmal teurer als normales Fleisch.\n\nFrau Ibrahim: Man braucht nicht unbedingt Tofu. Linsen, Bohnen und Eier sind sehr preiswert und sehr gesund. Das ist traditionelle Küche, auch in arabischen und indischen Ländern.\n\nHerr Wagner: Das stimmt – ich selbst liebe Linsensuppe. Vielleicht sollte ich mehr solche Gerichte auf die Karte setzen."}],"options":[{"id":"a","titleDe":"Herr Wagner","textDe":""},{"id":"b","titleDe":"Frau Ibrahim","textDe":""},{"id":"c","titleDe":"Niemand","textDe":""}],"questions":[],"matchItems":[{"id":"hoeren-1-4-1","textDe":"Vegetarisches Essen ist nicht immer billiger.","correctAd":"a"},{"id":"hoeren-1-4-2","textDe":"Restaurants ohne Fleisch sind erfolgreich in Großstädten.","correctAd":"b"},{"id":"hoeren-1-4-3","textDe":"In der Heimat gibt es viele gute vegetarische Gerichte.","correctAd":"b"},{"id":"hoeren-1-4-4","textDe":"Kinder brauchen Fleisch zum Wachsen.","correctAd":"c"},{"id":"hoeren-1-4-5","textDe":"Ich möchte mehr vegetarische Gerichte anbieten.","correctAd":"a"},{"id":"hoeren-1-4-6","textDe":"Gewürze machen vegetarisches Essen lecker.","correctAd":"b"}]}]},{"id":"hoeren-2","title":"نموذج Hören رقم 2","description":"نموذج استماع إضافي بمواضيع الجيران والعمل والنقل.","parts":[{"type":"tf-mc","title":"Teil 1 – رسائل متعددة","instructionsAr":"خمس رسائل قصيرة. أجب صح/خطأ واختيار من متعدد.","transcripts":[{"id":"h2-1","speaker":"Nachricht","textDe":"Hallo, hier ist die Hausverwaltung. Wir möchten Sie informieren: am Dienstag zwischen 9 und 12 Uhr ist das Wasser im ganzen Haus abgestellt, weil wir Rohre reparieren. Bitte füllen Sie vorher etwas Wasser ab. Vielen Dank!"},{"id":"h2-2","speaker":"Bahnsteig","textDe":"Information für Fahrgäste des ICE 625 nach München: Der Zug hat heute ausnahmsweise 20 Minuten Verspätung. Grund ist ein Signalproblem. Voraussichtliche Abfahrt: 15:50 Uhr."},{"id":"h2-3","speaker":"Voicemail","textDe":"Hallo Frau Hassan, hier ist Petra aus der Kita. Ihre Tochter Lina hat etwas Fieber. Können Sie sie bitte bis 15 Uhr abholen? Oder sagen Sie Ihrer Mutter Bescheid. Tel: 030 555123."},{"id":"h2-4","speaker":"Durchsage im Supermarkt","textDe":"Liebe Kunden, der Supermarkt schließt heute ausnahmsweise schon um 18 Uhr wegen einer Personalsitzung. Ab morgen sind wir wieder wie immer bis 22 Uhr für Sie da."},{"id":"h2-5","speaker":"Kollegin","textDe":"Hallo Jürgen, vergiss bitte nicht: Die Besprechung am Freitag ist nicht im Raum 305, sondern im Raum 412. Fang nicht früher an, wir kommen alle zusammen um 10 Uhr."}],"questions":[{"id":"hoeren-2-1-1","statementDe":"Am Dienstag gibt es kein Wasser im Haus, von 9 bis 12 Uhr.","correct":true},{"id":"hoeren-2-1-2","promptDe":"Was soll man vor Dienstag tun?","options":[{"id":"a","de":"Die Wohnung verlassen."},{"id":"b","de":"Wasser abfüllen."},{"id":"c","de":"Die Hausverwaltung anrufen."}],"correct":"b"},{"id":"hoeren-2-1-3","statementDe":"Der ICE 625 ist pünktlich.","correct":false},{"id":"hoeren-2-1-4","statementDe":"Lina hat Fieber und soll abgeholt werden.","correct":true},{"id":"hoeren-2-1-5","promptDe":"Bis wann soll Frau Hassan ihre Tochter abholen?","options":[{"id":"a","de":"Bis 13 Uhr."},{"id":"b","de":"Bis 15 Uhr."},{"id":"c","de":"Bis 17 Uhr."}],"correct":"b"},{"id":"hoeren-2-1-6","statementDe":"Der Supermarkt schließt heute wie immer um 22 Uhr.","correct":false},{"id":"hoeren-2-1-7","promptDe":"Wo ist die Besprechung am Freitag?","options":[{"id":"a","de":"In Raum 305."},{"id":"b","de":"In Raum 412."},{"id":"c","de":"Online."}],"correct":"b"}]},{"type":"tf-dialog","title":"Teil 2 – حوار في عيادة طبيب","instructionsAr":"حوار بين مريض وطبيب. أجب صح/خطأ.","transcripts":[{"id":"d2","textDe":"A: Guten Tag, Frau Nasser. Nehmen Sie bitte Platz. Was führt Sie heute zu mir?\nB: Guten Tag, Herr Doktor. Seit drei Tagen habe ich Kopfschmerzen und bin sehr müde.\nA: Haben Sie auch Fieber?\nB: Manchmal. Heute Morgen hatte ich 38 Grad.\nA: Nehmen Sie schon Medikamente?\nB: Ja, Paracetamol. Aber es hilft nicht viel.\nA: Machen Sie den Mund bitte auf... Gut. Es sieht nach einer Erkältung aus, vielleicht auch eine leichte Grippe. Ich schreibe Sie für drei Tage krank. Trinken Sie viel, ruhen Sie sich aus, und nehmen Sie weiterhin Paracetamol gegen die Schmerzen.\nB: Soll ich auch ein Antibiotikum nehmen?\nA: Nein, das hilft bei einer Virusinfektion nicht. Wenn es nach fünf Tagen nicht besser ist, kommen Sie wieder zu mir."}],"questions":[{"id":"hoeren-2-2-1","statementDe":"Frau Nasser hat seit einer Woche Probleme.","correct":false},{"id":"hoeren-2-2-2","statementDe":"Sie nimmt schon Medikamente.","correct":true},{"id":"hoeren-2-2-3","statementDe":"Der Arzt gibt ihr ein Antibiotikum.","correct":false},{"id":"hoeren-2-2-4","statementDe":"Sie soll viel Wasser trinken.","correct":true},{"id":"hoeren-2-2-5","statementDe":"Der Arzt schreibt sie für 5 Tage krank.","correct":false,"explanation":"لثلاثة أيام فقط."}]}]},{"id":"hoeren-3","title":"Hören – نموذج 3 (السفر والمواصلات)","description":"إعلانات في القطار، حوارات في المطار، شكاوى من النقل العام.","parts":[{"type":"tf-mc","title":"Teil 1 – خمسة إعلانات في محطة القطار","instructionsAr":"استمع إلى الإعلانات (أو اقرأ النصوص) وأجب عن الأسئلة. لكل إعلان سؤالان.","transcripts":[{"id":"t1","speaker":"Lautsprecher 1","textDe":"Achtung Reisende auf Gleis 5: Der ICE 723 nach München hat eine Verspätung von etwa 15 Minuten. Wir bitten um Ihr Verständnis. Grund ist eine technische Störung am Zug. Voraussichtliche Abfahrt: 14:35 Uhr."},{"id":"t2","speaker":"Lautsprecher 2","textDe":"Information für Reisende mit dem RE 4 nach Köln: Der Zug fährt heute ausnahmsweise von Gleis 8 statt Gleis 3. Der Zug ist pünktlich."},{"id":"t3","speaker":"Lautsprecher 3","textDe":"Verkaufsstart: Frühbuchertickets nach Berlin ab nur 19,90 Euro. Buchung bis spätestens 7 Tage vor Abfahrt. Nur online und in der App. Tickets sind nicht erstattbar."}],"questions":[{"id":"hoeren-3-1-1","promptDe":"Wie viel Verspätung hat der ICE nach München?","options":[{"id":"a","de":"5 Minuten."},{"id":"b","de":"15 Minuten."},{"id":"c","de":"50 Minuten."}],"correct":"b"},{"id":"hoeren-3-1-2","promptDe":"Was ist der Grund für die Verspätung?","options":[{"id":"a","de":"Schlechtes Wetter."},{"id":"b","de":"Eine technische Störung."},{"id":"c","de":"Personalmangel."}],"correct":"b"},{"id":"hoeren-3-1-3","promptDe":"Von welchem Gleis fährt der RE 4 nach Köln?","options":[{"id":"a","de":"Von Gleis 3."},{"id":"b","de":"Von Gleis 5."},{"id":"c","de":"Von Gleis 8."}],"correct":"c"},{"id":"hoeren-3-1-4","promptDe":"Bis wann muss man Frühbuchertickets buchen?","options":[{"id":"a","de":"7 Tage vor Abfahrt."},{"id":"b","de":"14 Tage vor Abfahrt."},{"id":"c","de":"Am Abfahrtstag."}],"correct":"a"},{"id":"hoeren-3-1-5","promptDe":"Wo kann man die Frühbuchertickets kaufen?","options":[{"id":"a","de":"Nur am Schalter."},{"id":"b","de":"Online und in der App."},{"id":"c","de":"Im Zug beim Schaffner."}],"correct":"b"},{"id":"hoeren-3-1-6","promptDe":"Kann man die Frühbuchertickets zurückgeben?","options":[{"id":"a","de":"Ja, immer."},{"id":"b","de":"Ja, gegen eine Gebühr."},{"id":"c","de":"Nein, nicht erstattbar."}],"correct":"c"}]},{"type":"match-speakers","title":"Teil 2 – خمسة أشخاص عن المواصلات","instructionsAr":"خمسة أشخاص يتحدثون عن وسيلة النقل المفضّلة لديهم. اربط كل شخص بالجملة المناسبة.","transcripts":[{"id":"p1","speaker":"Person 1 – Anja","textDe":"Ich fahre jeden Tag mit dem Fahrrad zur Arbeit, auch im Winter. Es ist gesund, kostet nichts und ich brauche keinen Parkplatz suchen. Außerdem tue ich der Umwelt etwas Gutes."},{"id":"p2","speaker":"Person 2 – Klaus","textDe":"Mein Auto ist mein zweites Zuhause. Ich brauche es für die Arbeit, weil ich Außendienstmitarbeiter bin und jeden Tag in eine andere Stadt muss. Ohne Auto kein Job."},{"id":"p3","speaker":"Person 3 – Yasmin","textDe":"Ich nehme die U-Bahn, weil ich mir kein Auto leisten kann. Es geht eigentlich, aber morgens ist es total voll. Manchmal komme ich zu spät zur Arbeit, wenn es Verspätungen gibt."},{"id":"p4","speaker":"Person 4 – Robert","textDe":"Ich fahre lieber mit dem Zug als mit dem Flugzeug. Es ist umweltfreundlicher und ich kann die ganze Zeit lesen oder arbeiten. Auch wenn es länger dauert."},{"id":"p5","speaker":"Person 5 – Sara","textDe":"Ich habe meinen Führerschein, aber ich fahre nie. Ich nehme immer ein Taxi oder Uber, wenn ich nicht laufen kann. Das ist bequem und ich muss nicht parken."}],"options":[{"id":"a","titleDe":"Diese Person nutzt das Auto aus beruflichen Gründen.","textDe":""},{"id":"b","titleDe":"Diese Person fährt aus Umweltgründen mit dem Rad.","textDe":""},{"id":"c","titleDe":"Diese Person bevorzugt die Bahn statt fliegen.","textDe":""},{"id":"d","titleDe":"Diese Person fährt nie selbst und nimmt Taxis.","textDe":""},{"id":"e","titleDe":"Diese Person ärgert sich über volle U-Bahnen.","textDe":""},{"id":"f","titleDe":"Diese Person reist gern mit dem Schiff.","textDe":""}],"questions":[],"matchItems":[{"id":"p1","textDe":"Anja","correctAd":"b"},{"id":"p2","textDe":"Klaus","correctAd":"a"},{"id":"p3","textDe":"Yasmin","correctAd":"e"},{"id":"p4","textDe":"Robert","correctAd":"c"},{"id":"p5","textDe":"Sara","correctAd":"d"}]},{"type":"tf-dialog","title":"Teil 3 – حوار في المطار","instructionsAr":"استمع إلى الحوار وأجب صح / خطأ.","transcripts":[{"id":"a1","textDe":"A: Guten Tag, ich möchte einchecken. Hier ist mein Ticket nach Istanbul.\nB: Den Pass bitte. – Danke. Sie haben einen Koffer aufzugeben?\nA: Ja, einen großen. Und einen kleinen Rucksack als Handgepäck.\nB: Bitte stellen Sie den Koffer auf die Waage. … Das sind 24 Kilo. Das ist 1 Kilo zu viel, das kostet 30 Euro extra.\nA: Oh, kann ich nicht etwas in meinen Rucksack packen?\nB: Ja, das geht. Aber das Handgepäck darf maximal 8 Kilo wiegen.\nA: Ich nehme nur ein Buch raus, dann passt es.\nB: Gut, jetzt sind es 23 Kilo. Hier ist Ihre Bordkarte. Gate B12, Boarding um 14:30.\nA: Vielen Dank. Wo finde ich die Sicherheitskontrolle?\nB: Geradeaus, dann links. Gute Reise!"}],"questions":[{"id":"hoeren-3-3-1","statementDe":"Der Mann fliegt nach Istanbul.","correct":true},{"id":"hoeren-3-3-2","statementDe":"Sein Koffer wiegt zuerst genau 23 Kilo.","correct":false,"explanation":"الوزن الأول 24 كيلو، ثم نقّصه إلى 23."},{"id":"hoeren-3-3-3","statementDe":"Er muss extra Geld bezahlen.","correct":false,"explanation":"لا، نقّص كتاباً وصار الوزن مناسباً."},{"id":"hoeren-3-3-4","statementDe":"Das Handgepäck darf höchstens 8 Kilo schwer sein.","correct":true},{"id":"hoeren-3-3-5","statementDe":"Sein Flug startet um 14:30 Uhr.","correct":false,"explanation":"14:30 هو وقت Boarding، وليس وقت إقلاع الطائرة."},{"id":"hoeren-3-3-6","statementDe":"Er muss zur Sicherheitskontrolle nach links.","correct":true}]},{"type":"match-opinions","title":"Teil 4 – نقاش في برنامج إذاعي","instructionsAr":"موضوع النقاش: \"هل يجب جعل النقل العام مجاني؟\" استمع وحدد رأي كل متحدث.","transcripts":[{"id":"r1","speaker":"Moderator","textDe":"Heute diskutieren wir: Sollte der öffentliche Nahverkehr in Deutschland kostenlos sein? Ich begrüße meine drei Gäste."},{"id":"r2","speaker":"Petra (Umweltexpertin)","textDe":"Auf jeden Fall! Wenn der Bus und die Bahn nichts kosten, lassen viele Menschen ihr Auto stehen. Das ist gut für die Umwelt und für die Städte. In Luxemburg funktioniert es schon."},{"id":"r3","speaker":"Hans (Politiker)","textDe":"Ich verstehe das Argument, aber wer soll das bezahlen? Wir müssten die Steuern erhöhen. Und die Busse wären total voll, mehr Personal und Fahrzeuge wären nötig. Das ist unrealistisch."},{"id":"r4","speaker":"Maria (Studentin)","textDe":"Mir reicht ein günstigeres Ticket, zum Beispiel das 49-Euro-Ticket. Komplett kostenlos finde ich nicht nötig. Aber teurer darf es auf keinen Fall werden, sonst fahren noch mehr mit dem Auto."}],"options":[{"id":"pro","titleDe":"Pro – ist dafür","textDe":""},{"id":"contra","titleDe":"Contra – ist dagegen","textDe":""},{"id":"mittel","titleDe":"Mittelmäßig – günstig statt kostenlos","textDe":""}],"questions":[],"matchItems":[{"id":"r2","textDe":"Petra","correctAd":"pro"},{"id":"r3","textDe":"Hans","correctAd":"contra"},{"id":"r4","textDe":"Maria","correctAd":"mittel"}]}]},{"id":"hoeren-4","title":"Hören – نموذج 4 (التسوق والخدمات)","description":"إعلانات في السوبرماركت، شكاوى، خدمة عملاء، مقارنة آراء.","parts":[{"type":"tf-mc","title":"Teil 1 – خمسة إعلانات في السوبرماركت","instructionsAr":"استمع (أو اقرأ) الإعلانات وأجب: لكل إعلان سؤال صح/خطأ + خيار من ثلاثة.","transcripts":[{"id":"t1","speaker":"Lautsprecher 1","textDe":"Sehr geehrte Kunden, wir bitten um Ihre Aufmerksamkeit. Heute haben wir ein Sonderangebot in der Obst- und Gemüseabteilung: Erdbeeren aus Spanien zum halben Preis – nur heute, nur 1 Euro 99 die 500-Gramm-Schale."},{"id":"t2","speaker":"Lautsprecher 2","textDe":"Liebe Kundinnen und Kunden, die Kassen 7, 8 und 9 sind leider geschlossen. Wir bitten Sie, sich an den Kassen 1 bis 6 anzustellen. Wir entschuldigen uns für die längere Wartezeit."},{"id":"t3","speaker":"Lautsprecher 3","textDe":"Ein kleiner Junge mit einer roten Jacke, ungefähr 5 Jahre alt, sucht seine Eltern. Er wartet bei der Information am Eingang. Bitte holen Sie ihn dort ab."},{"id":"t4","speaker":"Lautsprecher 4","textDe":"Aufgepasst, liebe Kunden! In der Tiefkühlabteilung gibt es heute Hähnchenfilet im Angebot: 1 Kilo nur 4 Euro 50 statt 7 Euro 90. Das Angebot gilt nur bis 18 Uhr."},{"id":"t5","speaker":"Lautsprecher 5","textDe":"Liebe Kunden, unser Markt schließt heute ausnahmsweise bereits um 19 Uhr. Wir bitten Sie, Ihren Einkauf rechtzeitig zu beenden. Ab morgen sind wir wieder zu den normalen Zeiten von 8 bis 22 Uhr für Sie da."}],"questions":[{"id":"h4-1-1","promptDe":"Die Erdbeeren kosten heute …","options":[{"id":"a","de":"1,99 € pro Schale."},{"id":"b","de":"1,99 € pro Kilo."},{"id":"c","de":"99 Cent pro Schale."}],"correct":"a","explanation":"الإعلان يقول \"1 Euro 99 die 500-Gramm-Schale\" أي السلّة الواحدة بـ 1.99€."},{"id":"h4-1-2","promptDe":"Welche Kassen sind offen?","options":[{"id":"a","de":"Kassen 7, 8 und 9."},{"id":"b","de":"Kassen 1 bis 6."},{"id":"c","de":"Alle Kassen."}],"correct":"b","explanation":"\"die Kassen 7, 8 und 9 sind … geschlossen … an den Kassen 1 bis 6 anzustellen\". مغلقة 7-9، مفتوحة 1-6."},{"id":"h4-1-3","promptDe":"Wo wartet der kleine Junge auf seine Eltern?","options":[{"id":"a","de":"An der Kasse."},{"id":"b","de":"Bei der Information am Eingang."},{"id":"c","de":"In der Obstabteilung."}],"correct":"b","explanation":"\"wartet bei der Information am Eingang\"."},{"id":"h4-1-4","promptDe":"Wie lange gilt das Hähnchenfilet-Angebot?","options":[{"id":"a","de":"Bis 18 Uhr."},{"id":"b","de":"Bis 19 Uhr."},{"id":"c","de":"Bis 22 Uhr."}],"correct":"a","explanation":"\"Das Angebot gilt nur bis 18 Uhr\"."},{"id":"h4-1-5","promptDe":"Wann schließt der Markt heute?","options":[{"id":"a","de":"Um 18 Uhr."},{"id":"b","de":"Um 19 Uhr."},{"id":"c","de":"Um 22 Uhr."}],"correct":"b","explanation":"\"unser Markt schließt heute ausnahmsweise bereits um 19 Uhr\". لاحظ ausnahmsweise (استثنائياً)."}]},{"type":"tf-dialog","title":"Teil 2 – حوار: شكوى في خدمة العملاء","instructionsAr":"استمع للحوار بين زبونة وموظف في \"خدمة العملاء\" بمحل إلكترونيات. أجب صح/خطأ.","transcripts":[{"id":"t1","speaker":"Mitarbeiter","textDe":"Guten Tag, wie kann ich Ihnen helfen?"},{"id":"t2","speaker":"Frau Faruk","textDe":"Guten Tag. Ich habe vor zwei Wochen einen Wasserkocher hier gekauft, aber er funktioniert nicht mehr. Hier ist der Kassenbon."},{"id":"t3","speaker":"Mitarbeiter","textDe":"Tut mir leid. Was genau ist das Problem?"},{"id":"t4","speaker":"Frau Faruk","textDe":"Er schaltet sich nicht mehr ein. Gestern habe ich ihn benutzt, alles war normal, aber heute Morgen geht er einfach nicht mehr an."},{"id":"t5","speaker":"Mitarbeiter","textDe":"Verstehe. Sie können den Wasserkocher gerne umtauschen. Möchten Sie das gleiche Modell oder ein anderes? Oder wir geben Ihnen das Geld zurück."},{"id":"t6","speaker":"Frau Faruk","textDe":"Ich möchte am liebsten das gleiche Modell. Es war gut für den Preis."},{"id":"t7","speaker":"Mitarbeiter","textDe":"Kein Problem. Ich hole Ihnen ein neues. Bitte warten Sie hier kurz."},{"id":"t8","speaker":"Frau Faruk","textDe":"Vielen Dank. Eine Frage noch: Wie lange ist die Garantie auf das neue Gerät?"},{"id":"t9","speaker":"Mitarbeiter","textDe":"Auf alle Haushaltsgeräte haben wir 24 Monate Garantie. Sie bekommen einen neuen Kassenbon mit dem heutigen Datum, das ist wichtig."}],"questions":[{"id":"h4-2-1","statementDe":"Frau Faruk hat den Wasserkocher heute gekauft.","statementAr":"السيدة فاروق اشترت الغلاية اليوم.","correct":false,"explanation":"هي قالت \"vor zwei Wochen\" — منذ أسبوعين."},{"id":"h4-2-2","statementDe":"Der Wasserkocher schaltet sich nicht mehr ein.","statementAr":"الغلاية لا تُشغّل بعد الآن.","correct":true,"explanation":"\"Er schaltet sich nicht mehr ein\"."},{"id":"h4-2-3","statementDe":"Der Mitarbeiter bietet ihr das Geld zurück oder einen Umtausch.","statementAr":"الموظف يعرض إعادة المال أو الاستبدال.","correct":true,"explanation":"\"umtauschen … Oder wir geben Ihnen das Geld zurück\"."},{"id":"h4-2-4","statementDe":"Frau Faruk möchte ein anderes Modell.","statementAr":"السيدة تريد موديلاً مختلفاً.","correct":false,"explanation":"هي قالت صراحة \"das gleiche Modell\" — نفس الموديل."},{"id":"h4-2-5","statementDe":"Die Garantie auf Haushaltsgeräte ist 24 Monate.","statementAr":"الضمان على الأجهزة المنزلية 24 شهراً.","correct":true,"explanation":"\"24 Monate Garantie\"."},{"id":"h4-2-6","statementDe":"Der neue Kassenbon hat das Datum von vor zwei Wochen.","statementAr":"الإيصال الجديد سيحمل تاريخ ما قبل أسبوعين.","correct":false,"explanation":"\"einen neuen Kassenbon mit dem heutigen Datum\" — التاريخ الجديد، اليوم."}]},{"type":"match-opinions","title":"Teil 4 – آراء حول التسوّق عبر الإنترنت","instructionsAr":"استمع لأربعة أشخاص يتحدثون عن التسوق عبر الإنترنت. اربط كل شخص برأيه (إيجابي / سلبي / محايد).","transcripts":[{"id":"r1","speaker":"Hassan","textDe":"Ich bestelle alles online: Kleidung, Bücher, sogar Lebensmittel. Es ist viel günstiger und ich spare so viel Zeit. Im Geschäft stehe ich dann nicht stundenlang in der Schlange."},{"id":"r2","speaker":"Frau Lehmann","textDe":"Ich bin total dagegen. Online sieht man die Qualität nicht, oft passt die Größe nicht, und das Zurückschicken ist nervig. Ich gehe lieber in den Laden und probiere alles an."},{"id":"r3","speaker":"Lina","textDe":"Es kommt drauf an. Bücher und Elektronik kaufe ich online, aber Kleidung muss ich anfassen und anprobieren. Da ist mir der Laden wichtig."},{"id":"r4","speaker":"Herr Becker","textDe":"Online ist super praktisch, aber wir vergessen die kleinen Geschäfte in der Innenstadt. Wenn die alle schließen, wird unsere Stadt langweilig. Ich versuche bewusst lokal zu kaufen."}],"questions":[],"options":[{"id":"positiv","titleDe":"positiv (Online ist toll!)","textDe":"مع التسوق عبر الإنترنت"},{"id":"negativ","titleDe":"negativ (Online ist schlecht!)","textDe":"ضد التسوق عبر الإنترنت"},{"id":"gemischt","titleDe":"gemischt (es kommt drauf an)","textDe":"يعتمد على المنتج"},{"id":"lokal","titleDe":"pro Innenstadt / kleine Läden","textDe":"يفضل المحال المحلية"}],"matchItems":[{"id":"r1","textDe":"Hassan","correctAd":"positiv"},{"id":"r2","textDe":"Frau Lehmann","correctAd":"negativ"},{"id":"r3","textDe":"Lina","correctAd":"gemischt"},{"id":"r4","textDe":"Herr Becker","correctAd":"lokal"}]}]},{"id":"hoeren-5","title":"Hören 5 – العمل والصحة (نمط Goethe B1)","description":"نموذج جديد على نمط Goethe B1: 4 إعلانات قصيرة (صح/خطأ)، حوار في عيادة طبيب، مقابلة إذاعية مع طبيب نفسي.","parts":[{"type":"tf-mc","title":"Teil 1 – إعلانات وأخبار قصيرة","instructionsAr":"ستسمع 4 نصوص قصيرة (إعلانات/أخبار). لكل نص ستجد عبارتين، واحدة صح/خطأ والثانية اختيار من متعدد.","transcripts":[{"id":"h5-t1","speaker":"Durchsage am Hauptbahnhof München","textDe":"Sehr geehrte Fahrgäste, Achtung an Gleis 7: Der ICE 925 nach Berlin Hauptbahnhof, geplante Abfahrt 14:30 Uhr, hat heute leider eine Verspätung von 35 Minuten. Grund ist eine technische Störung. Wir bitten um Ihr Verständnis und entschuldigen uns für die Unannehmlichkeiten."},{"id":"h5-t2","speaker":"Werbung im Radio","textDe":"Nur dieses Wochenende! Das Sportgeschäft \"Aktivsport\" in der Schillerstraße bietet 30% Rabatt auf alle Laufschuhe. Egal ob Anfänger oder Profi – bei uns finden Sie das Richtige. Wir haben Samstag von 9 bis 20 Uhr und Sonntag von 11 bis 18 Uhr für Sie geöffnet."},{"id":"h5-t3","speaker":"Anrufbeantworter Arztpraxis Dr. Klein","textDe":"Sie haben die Praxis von Dr. Klein erreicht. Vom 1. bis 15. Juli ist die Praxis wegen Urlaub geschlossen. In dringenden Fällen wenden Sie sich bitte an die Vertretung, Dr. Schmidt, in der Hauptstraße 25, Telefon 089-555-1234. Bei Notfällen wählen Sie bitte 112."},{"id":"h5-t4","speaker":"Wetterbericht im Radio","textDe":"Und nun zum Wetter für morgen: Im Norden Deutschlands wird es regnerisch und kühl mit Höchstwerten um 14 Grad. Im Süden dagegen erwartet uns ein sonniger Tag mit Temperaturen bis zu 22 Grad. In den Bergen kann es am Nachmittag zu Gewittern kommen."}],"questions":[{"id":"h5-1-1","statementDe":"Der ICE nach Berlin fährt heute pünktlich ab.","statementAr":"قطار ICE إلى برلين يغادر اليوم في موعده.","correct":false,"explanation":"\"hat heute leider eine Verspätung von 35 Minuten\" – التأخير 35 دقيقة."},{"id":"h5-1-2","promptDe":"Was ist der Grund für die Verspätung?","options":[{"id":"a","de":"Schlechtes Wetter."},{"id":"b","de":"Eine technische Störung."},{"id":"c","de":"Ein Streik."}],"correct":"b","explanation":"النص يقول: \"Grund ist eine technische Störung\"."},{"id":"h5-1-3","statementDe":"Der Rabatt im Sportgeschäft gilt nur für Anfänger-Laufschuhe.","statementAr":"الخصم في متجر الرياضة فقط لأحذية المبتدئين.","correct":false,"explanation":"\"alle Laufschuhe\" + \"Anfänger oder Profi\" – الخصم لجميع الأحذية."},{"id":"h5-1-4","promptDe":"Wann ist das Geschäft am Sonntag geöffnet?","options":[{"id":"a","de":"Von 9 bis 20 Uhr."},{"id":"b","de":"Von 11 bis 18 Uhr."},{"id":"c","de":"Geschlossen."}],"correct":"b","explanation":"النص: \"Sonntag von 11 bis 18 Uhr\"."},{"id":"h5-1-5","statementDe":"Dr. Klein ist im Juli zwei Wochen im Urlaub.","statementAr":"الطبيب كلاين في إجازة لأسبوعين في يوليو.","correct":true,"explanation":"\"vom 1. bis 15. Juli\" = 15 يوماً = أسبوعان."},{"id":"h5-1-6","promptDe":"Was sollte man bei einem Notfall machen?","options":[{"id":"a","de":"Die Praxis von Dr. Schmidt anrufen."},{"id":"b","de":"Die Nummer 112 wählen."},{"id":"c","de":"Bis zum 16. Juli warten."}],"correct":"b","explanation":"\"Bei Notfällen wählen Sie bitte 112\"."},{"id":"h5-1-7","statementDe":"Im Süden Deutschlands wird es morgen regnerisch.","statementAr":"في جنوب ألمانيا غداً سيكون الجو ممطراً.","correct":false,"explanation":"\"Im Süden ... ein sonniger Tag\" – جنوبي ألمانيا مشمس."},{"id":"h5-1-8","promptDe":"Wo kann es am Nachmittag Gewitter geben?","options":[{"id":"a","de":"Im Norden."},{"id":"b","de":"In den Bergen."},{"id":"c","de":"Nirgendwo."}],"correct":"b","explanation":"النص: \"In den Bergen kann es am Nachmittag zu Gewittern kommen\"."}]},{"type":"tf-dialog","title":"Teil 2 – حوار في عيادة الطبيب","instructionsAr":"استمع للحوار بين المريض والطبيب. اقرر إن كانت كل عبارة صح أم خطأ.","transcripts":[{"id":"h5-d1","speaker":"Arzt + Patient","textDe":"**Arzt:** Guten Tag, Herr Yousef. Setzen Sie sich bitte. Was kann ich für Sie tun?\n\n**Patient:** Guten Tag, Herr Doktor. Ich habe seit fünf Tagen starke Halsschmerzen und Husten. Außerdem hatte ich gestern Fieber, etwa 38,5 Grad.\n\n**Arzt:** Haben Sie auch Kopf- oder Gliederschmerzen?\n\n**Patient:** Ja, Kopfschmerzen schon, aber meine Glieder tun mir nicht weh.\n\n**Arzt:** Und Sie haben keine Probleme beim Atmen?\n\n**Patient:** Doch, manchmal. Besonders nachts, wenn ich liege.\n\n**Arzt:** Ich werde Sie kurz untersuchen. ... So, der Hals ist sehr rot und die Lymphknoten sind geschwollen. Sie haben eine starke Erkältung, vielleicht sogar eine leichte Bronchitis.\n\n**Patient:** Und was kann ich dagegen tun?\n\n**Arzt:** Ich verschreibe Ihnen ein Antibiotikum für sieben Tage und ein Hustenmittel. Trinken Sie viel warmen Tee mit Honig und ruhen Sie sich aus. Ich schreibe Sie für drei Tage krank.\n\n**Patient:** Vielen Dank, Herr Doktor. Wann soll ich wieder kommen?\n\n**Arzt:** Wenn die Beschwerden in einer Woche nicht besser werden, kommen Sie bitte noch einmal. Sonst können Sie nach den drei Tagen wieder arbeiten."}],"questions":[{"id":"h5-2-1","statementDe":"Herr Yousef hat seit einer Woche Halsschmerzen.","statementAr":"السيد يوسف يعاني من ألم في الحنجرة منذ أسبوع.","correct":false,"explanation":"قال: \"seit fünf Tagen\" – منذ 5 أيام، ليس أسبوعاً."},{"id":"h5-2-2","statementDe":"Er hatte gestern Fieber.","statementAr":"كان لديه حمّى أمس.","correct":true,"explanation":"قال: \"hatte ich gestern Fieber, etwa 38,5 Grad\"."},{"id":"h5-2-3","statementDe":"Herr Yousef hat Probleme beim Atmen, besonders nachts.","statementAr":"لديه مشكلة في التنفس، خاصة ليلاً.","correct":true,"explanation":"قال: \"manchmal. Besonders nachts, wenn ich liege\"."},{"id":"h5-2-4","statementDe":"Der Arzt verschreibt ihm nur Tee und Ruhe.","statementAr":"الطبيب وصف له الشاي والراحة فقط.","correct":false,"explanation":"قال الطبيب: \"ein Antibiotikum für sieben Tage und ein Hustenmittel\" – موصوف دواء."},{"id":"h5-2-5","statementDe":"Er bekommt einen Krankenschein für drei Tage.","statementAr":"حصل على إجازة مرضية لـ 3 أيام.","correct":true,"explanation":"قال الطبيب: \"Ich schreibe Sie für drei Tage krank\"."},{"id":"h5-2-6","statementDe":"Wenn er nach einer Woche nicht besser ist, soll er wiederkommen.","statementAr":"إذا لم يتحسّن بعد أسبوع، عليه أن يعود.","correct":true,"explanation":"قال الطبيب: \"in einer Woche nicht besser werden, kommen Sie noch einmal\"."}]},{"type":"match-opinions","title":"Teil 3 – مقابلة إذاعية: الإجهاد في العمل","instructionsAr":"استمع لـ 4 آراء عن الإجهاد في العمل. اربط كل شخص برأيه (a-e). يوجد 5 آراء، 4 منها فقط صحيحة.","transcripts":[{"id":"h5-int","textDe":"**Moderatorin:** Heute sprechen wir über das Thema Stress am Arbeitsplatz. Vier Hörer haben ihre Erfahrung geteilt.\n\n**Hörer 1 - Sami (35, Ingenieur):** Ich arbeite oft 50 Stunden in der Woche und manchmal auch am Wochenende. Mein Chef erwartet, dass ich immer erreichbar bin, sogar im Urlaub. Das macht mich krank. Letzten Monat war ich zwei Wochen wegen Burnout krank.\n\n**Hörerin 2 - Karin (42, Lehrerin):** Mein Beruf ist anstrengend, aber ich habe gelernt, abzuschalten. Nach der Arbeit mache ich Yoga, gehe spazieren oder treffe Freunde. Diese Aktivitäten helfen mir wirklich, mit dem Stress umzugehen.\n\n**Hörer 3 - Tobias (28, Verkäufer):** Bei mir ist das Problem die Kunden. Manchmal sind sie unhöflich oder beschweren sich über Dinge, an denen ich nicht schuld bin. Das nimmt mich emotional sehr mit.\n\n**Hörerin 4 - Frau Wagner (55, Krankenschwester):** In meinem Beruf gibt es zu wenig Personal, deshalb müssen wir alle länger arbeiten. Ich denke oft daran, den Beruf zu wechseln, aber ich liebe es, Menschen zu helfen."}],"questions":[],"options":[{"id":"a","titleDe":"zu lange Arbeitszeiten","textDe":"ساعات عمل طويلة جداً"},{"id":"b","titleDe":"Probleme mit Kunden","textDe":"مشاكل مع الزبائن"},{"id":"c","titleDe":"Personalmangel","textDe":"نقص في الموظفين"},{"id":"d","titleDe":"gut mit Stress umgehen","textDe":"تتعامل مع الضغط جيداً"},{"id":"e","titleDe":"zu niedriger Lohn","textDe":"الراتب منخفض جداً"}],"matchItems":[{"id":"r1","textDe":"Sami","correctAd":"a"},{"id":"r2","textDe":"Karin","correctAd":"d"},{"id":"r3","textDe":"Tobias","correctAd":"b"},{"id":"r4","textDe":"Frau Wagner","correctAd":"c"}]}]},{"id":"hoeren-6","title":"Hören 6 – التعليم والاندماج (نمط telc B1)","description":"نموذج جديد: إعلانات قصيرة في مدرسة لغة، حوار مع موظف Ausländerbehörde، نقاش حول دورات الاندماج.","parts":[{"type":"tf-mc","title":"Teil 1 – إعلانات قصيرة","instructionsAr":"ستسمع 3 نصوص قصيرة. لكل نص ستجد عبارتين – صح/خطأ ثم اختيار من متعدد.","transcripts":[{"id":"h6-t1","speaker":"Durchsage in der Volkshochschule","textDe":"Liebe Teilnehmer, der heutige B1-Kurs in Raum 12 fällt leider aus, weil die Lehrerin krank ist. Der Unterricht wird nächsten Montag, 18 Uhr, im selben Raum nachgeholt. Wenn Sie Fragen haben, kommen Sie bitte zur Anmeldung im Erdgeschoss. Vielen Dank für Ihr Verständnis."},{"id":"h6-t2","speaker":"Anrufbeantworter Ausländerbehörde Frankfurt","textDe":"Sie haben die Ausländerbehörde Frankfurt erreicht. Unsere Sprechzeiten sind Montag bis Freitag, 8 bis 12 Uhr, und Donnerstag zusätzlich 14 bis 18 Uhr. Termine vereinbaren Sie bitte online über unsere Website. Notfälle melden Sie sich bitte direkt am Eingang. Wir rufen Sie schnellstmöglich zurück."},{"id":"h6-t3","speaker":"Werbung im Radio","textDe":"Die Sprachschule \"Deutsch aktiv\" startet im September neue Integrationskurse für alle Niveaus von A1 bis B2. Die Kurse finden vormittags und abends statt. Mit dem BAMF-Gutschein zahlen Sie nur einen Teil der Kosten. Anmelden können Sie sich ab sofort online oder telefonisch. Wir freuen uns auf Sie!"}],"questions":[{"id":"hoeren-6-1-1","statementDe":"Der heutige B1-Kurs findet wie geplant statt.","correct":false,"explanation":"النص يقول \"fällt aus\" – أُلغي."},{"id":"hoeren-6-1-2","promptDe":"Wann wird der Kurs nachgeholt?","options":[{"id":"a","de":"Morgen früh."},{"id":"b","de":"Nächsten Montag, 18 Uhr."},{"id":"c","de":"In zwei Wochen."}],"correct":"b","explanation":"\"nächsten Montag, 18 Uhr\"."},{"id":"hoeren-6-1-3","statementDe":"Termine bei der Ausländerbehörde bekommt man online.","correct":true},{"id":"hoeren-6-1-4","promptDe":"Wann hat die Behörde am längsten geöffnet?","options":[{"id":"a","de":"Montag."},{"id":"b","de":"Mittwoch."},{"id":"c","de":"Donnerstag."}],"correct":"c","explanation":"الخميس مفتوح حتى 18، باقي الأيام حتى 12."},{"id":"hoeren-6-1-5","statementDe":"Mit BAMF-Gutschein bekommt man eine Ermäßigung.","correct":true,"explanation":"\"zahlen Sie nur einen Teil der Kosten\"."},{"id":"hoeren-6-1-6","promptDe":"Welche Kursniveaus bietet die Sprachschule an?","options":[{"id":"a","de":"Nur A1 und A2."},{"id":"b","de":"Von A1 bis B2."},{"id":"c","de":"Nur B1 und B2."}],"correct":"b"}]},{"type":"tf-dialog","title":"Teil 2 – حوار في Ausländerbehörde","instructionsAr":"استمع للحوار وأجب صح / خطأ.","transcripts":[{"id":"h6-d1","textDe":"Beamter: Guten Tag. Wie kann ich Ihnen helfen?\nFrau Sarah: Guten Tag. Ich brauche eine Verlängerung meines Aufenthaltstitels.\nBeamter: Haben Sie alle Unterlagen dabei?\nFrau Sarah: Ich habe meinen Pass, das alte Aufenthaltsdokument und eine Bescheinigung über meinen Sprachkurs.\nBeamter: Brauchen Sie auch einen Nachweis über Ihre finanzielle Lage. Arbeiten Sie?\nFrau Sarah: Ja, ich arbeite seit einem Jahr in einem Café, halbtags.\nBeamter: Bringen Sie bitte die letzten drei Gehaltsabrechnungen mit. Außerdem brauchen wir eine aktuelle Krankenversicherungs-Bescheinigung.\nFrau Sarah: Habe ich beides nicht dabei. Kann ich die später per Post schicken?\nBeamter: Nein, bitte kommen Sie persönlich vorbei, sobald Sie alles haben. Hier ist mein Termin-Zettel."}],"questions":[{"id":"hoeren-6-2-1","statementDe":"Frau Sarah möchte ihren Aufenthaltstitel verlängern.","correct":true},{"id":"hoeren-6-2-2","statementDe":"Sie hat eine Sprachkurs-Bescheinigung dabei.","correct":true},{"id":"hoeren-6-2-3","statementDe":"Frau Sarah arbeitet Vollzeit.","correct":false,"explanation":"قالت \"halbtags\" – نصف الدوام."},{"id":"hoeren-6-2-4","statementDe":"Sie kann die fehlenden Dokumente per Post schicken.","correct":false,"explanation":"الموظف رفض ذلك: \"Nein, bitte kommen Sie persönlich vorbei\"."},{"id":"hoeren-6-2-5","statementDe":"Sie braucht eine Krankenversicherungs-Bescheinigung.","correct":true},{"id":"hoeren-6-2-6","statementDe":"Sie braucht 5 Gehaltsabrechnungen.","correct":false,"explanation":"فقط 3 (الأخيرة)."}]}]},{"id":"hoeren-7","title":"Hören 7 – التسوّق والخدمات","description":"إعلانات في السوبرماركت، حوار في صالة هاتف محمول، نقاش عن التسوّق الإلكتروني.","parts":[{"type":"tf-mc","title":"Teil 1 – إعلانات قصيرة","instructionsAr":"3 نصوص قصيرة، لكلّ نصّ صح/خطأ ثم اختيار من متعدّد.","transcripts":[{"id":"h7-t1","speaker":"Durchsage im Supermarkt","textDe":"Liebe Kunden, an unserer Käse-Theke haben wir heute eine besondere Aktion: 100 g französischer Brie zum halben Preis. Außerdem finden Sie an der Kasse 3 frische Brötchen für nur 1 €. Das Angebot gilt nur bis 18 Uhr. Vielen Dank für Ihren Einkauf."},{"id":"h7-t2","speaker":"Werbung im Radio","textDe":"Die Apotheke \"Sonnen-Apotheke\" in der Hauptstraße 12 hat ab dem 1. April neue Öffnungszeiten: Montag bis Freitag von 8 bis 19 Uhr, Samstag bis 14 Uhr. Sonntag ist die Notdienst-Nummer 116117 erreichbar. Wir freuen uns auf Ihren Besuch."},{"id":"h7-t3","speaker":"Anrufbeantworter eines Friseurs","textDe":"Sie haben den Friseursalon \"Beauty&Style\" erreicht. Aktuell sind wir nicht im Salon. Unsere Termine vereinbaren Sie online auf unserer Website oder per WhatsApp unter 0151-12345678. Sprechen Sie nach dem Signal Ihren Namen und Ihren Wunschtermin auf den Anrufbeantworter. Wir rufen Sie zurück."}],"questions":[{"id":"hoeren-7-1-1","statementDe":"Der Brie kostet heute den vollen Preis.","correct":false,"explanation":"\"zum halben Preis\"."},{"id":"hoeren-7-1-2","promptDe":"Wie viel kosten die 3 Brötchen?","options":[{"id":"a","de":"1 €."},{"id":"b","de":"3 €."},{"id":"c","de":"50 Cent."}],"correct":"a"},{"id":"hoeren-7-1-3","statementDe":"Die Apotheke öffnet samstags bis 14 Uhr.","correct":true},{"id":"hoeren-7-1-4","promptDe":"Wer hilft am Sonntag?","options":[{"id":"a","de":"Die Apotheke direkt."},{"id":"b","de":"Der Notdienst über 116117."},{"id":"c","de":"Niemand."}],"correct":"b"},{"id":"hoeren-7-1-5","statementDe":"Im Friseursalon kann man Termine per WhatsApp machen.","correct":true},{"id":"hoeren-7-1-6","promptDe":"Was soll man nach dem Signal sagen?","options":[{"id":"a","de":"Nur den Namen."},{"id":"b","de":"Name und Wunschtermin."},{"id":"c","de":"Die Telefonnummer."}],"correct":"b"}]},{"type":"tf-dialog","title":"Teil 2 – حوار في محلّ هاتف محمول","instructionsAr":"استمع للحوار وحدّد صح/خطأ.","transcripts":[{"id":"h7-d1","textDe":"Verkäufer: Guten Tag, kann ich Ihnen helfen?\nFrau Yara: Guten Tag. Ich möchte einen neuen Handyvertrag. Mein alter Vertrag läuft nächste Woche aus.\nVerkäufer: Wie viele Daten brauchen Sie pro Monat?\nFrau Yara: Ich nutze viel WhatsApp und YouTube. Vielleicht 20 GB?\nVerkäufer: Wir haben ein Angebot: 25 GB für 19,99 € im Monat, ohne Mindestlaufzeit, Sie können jeden Monat kündigen.\nFrau Yara: Das klingt gut. Sind Anrufe und SMS auch enthalten?\nVerkäufer: Ja, Flatrate für Telefon und SMS in Deutschland. Im Ausland zahlen Sie extra. Bei EU-Ländern fällt keine Roaming-Gebühr an.\nFrau Yara: Perfekt. Ich brauche oft Roaming nach Frankreich, weil meine Schwester dort lebt.\nVerkäufer: Dann passt der Tarif perfekt für Sie. Brauchen Sie auch ein neues Handy?\nFrau Yara: Nein, mein Handy ist erst ein Jahr alt. Ich nehme nur den Tarif.\nVerkäufer: Sehr gut. Ich brauche Ihren Personalausweis und Ihre IBAN."}],"questions":[{"id":"hoeren-7-2-1","statementDe":"Frau Yaras alter Vertrag ist noch lange gültig.","correct":false,"explanation":"\"läuft nächste Woche aus\"."},{"id":"hoeren-7-2-2","statementDe":"Sie braucht etwa 20 GB pro Monat.","correct":true},{"id":"hoeren-7-2-3","statementDe":"Der Tarif kostet 19,99 € im Monat.","correct":true},{"id":"hoeren-7-2-4","statementDe":"Sie hat eine 2-jährige Mindestlaufzeit.","correct":false,"explanation":"\"ohne Mindestlaufzeit\"."},{"id":"hoeren-7-2-5","statementDe":"In EU-Ländern zahlt sie Roaming-Gebühren.","correct":false},{"id":"hoeren-7-2-6","statementDe":"Sie kauft auch ein neues Handy.","correct":false,"explanation":"\"Nein, mein Handy ist erst ein Jahr alt\"."},{"id":"hoeren-7-2-7","statementDe":"Für den Vertrag braucht sie Personalausweis und IBAN.","correct":true}]}]},{"id":"hoeren-8","title":"Hören 8 – العمل والمكاتب","description":"إعلانات داخل شركة، حوار في مكتب التوظيف Agentur für Arbeit، ومتحدّثون عن خبراتهم.","parts":[{"type":"tf-mc","title":"Teil 1 – إعلانات قصيرة","instructionsAr":"استمع لثلاثة نصوص قصيرة وأجب.","transcripts":[{"id":"h8-t1","speaker":"Durchsage in der Firma","textDe":"Liebe Mitarbeiter, am Freitag findet von 14 bis 16 Uhr eine Pflicht-Schulung zum Thema Datenschutz statt. Bitte erscheinen Sie pünktlich im Konferenzraum 1. Wer nicht teilnehmen kann, meldet sich bei der Personalabteilung bis Mittwoch 12 Uhr."},{"id":"h8-t2","speaker":"Anrufbeantworter Arbeitsagentur","textDe":"Sie haben die Agentur für Arbeit Düsseldorf erreicht. Termine vereinbaren Sie bitte online über die Job-Börse oder telefonisch unter der Service-Nummer 0800-455500. Anträge auf Arbeitslosengeld können Sie direkt online stellen. Persönliche Termine sind nach Vereinbarung montags bis donnerstags von 8 bis 16 Uhr möglich."},{"id":"h8-t3","speaker":"Werbung im Radio","textDe":"Die Volkshochschule Bonn bietet ab März einen kostenlosen Bewerbungs-Workshop für Migranten an. Sie lernen Lebenslauf und Anschreiben auf Deutsch zu schreiben. Auch das Vorstellungsgespräch wird mit echten Personalern geübt. Anmeldung unter 0228-12345 oder direkt im Bürgerbüro."}],"questions":[{"id":"hoeren-8-1-1","statementDe":"Die Schulung am Freitag ist freiwillig.","correct":false,"explanation":"\"Pflicht-Schulung\"."},{"id":"hoeren-8-1-2","promptDe":"Bis wann kann man sich abmelden?","options":[{"id":"a","de":"Mittwoch 12 Uhr."},{"id":"b","de":"Freitag 14 Uhr."},{"id":"c","de":"Donnerstag 18 Uhr."}],"correct":"a"},{"id":"hoeren-8-1-3","statementDe":"Bei der Arbeitsagentur kann man online Termine machen.","correct":true},{"id":"hoeren-8-1-4","promptDe":"Wann sind persönliche Termine möglich?","options":[{"id":"a","de":"Montag bis Freitag."},{"id":"b","de":"Montag bis Donnerstag 8-16 Uhr."},{"id":"c","de":"Nur am Wochenende."}],"correct":"b"},{"id":"hoeren-8-1-5","statementDe":"Der Bewerbungs-Workshop ist kostenpflichtig.","correct":false,"explanation":"\"kostenlosen Bewerbungs-Workshop\"."},{"id":"hoeren-8-1-6","promptDe":"Was wird im Workshop geübt?","options":[{"id":"a","de":"Nur Lebenslauf."},{"id":"b","de":"Lebenslauf, Anschreiben und Vorstellungsgespräch."},{"id":"c","de":"Nur Deutsch-Grammatik."}],"correct":"b"}]},{"type":"match-speakers","title":"Teil 2 – خمسة متحدّثين عن العمل","instructionsAr":"تطابق كلّ متحدّث مع الجملة المناسبة (a-f). يتبقّى عبارة واحدة لا تستخدم.","transcripts":[{"id":"h8-s1","speaker":"Person 1 – Murat","textDe":"Ich arbeite in einer Pflegestelle für Senioren. Die Ausbildung ist hart, aber meine Lehrerin sagt, ich mache gute Fortschritte. In zwei Jahren bin ich examinierter Altenpfleger."},{"id":"h8-s2","speaker":"Person 2 – Linda","textDe":"Seit Corona arbeite ich komplett von zu Hause. Ich kann mir die Arbeit selbst einteilen und mit den Kindern spielen. Mein Chef ist nur per Video-Call präsent."},{"id":"h8-s3","speaker":"Person 3 – Sami","textDe":"Ich habe in Damaskus 10 Jahre als Deutschlehrer gearbeitet. Jetzt mache ich Anerkennung beim Schulamt und hoffe, bald wieder unterrichten zu können."},{"id":"h8-s4","speaker":"Person 4 – Petra","textDe":"Ich verdiene gut bei der Bank — 4.500 brutto. Aber ich arbeite oft bis 20 Uhr, das ist mir zu viel. Mit kleinen Kindern wird das schwierig."},{"id":"h8-s5","speaker":"Person 5 – Khaled","textDe":"Ich studiere Maschinenbau an der TU Berlin und arbeite 12 Stunden pro Woche in einem Café. Mit dem Studentenjob verdiene ich genug für die Miete."}],"questions":[],"options":[{"id":"a","titleDe":"Diese Person ist mit dem Gehalt zufrieden, aber unzufrieden mit den Arbeitszeiten.","textDe":""},{"id":"b","titleDe":"Diese Person arbeitet im Homeoffice und schätzt die Freiheit.","textDe":""},{"id":"c","titleDe":"Diese Person hat in Syrien als Lehrer gearbeitet und möchte das in Deutschland fortsetzen.","textDe":""},{"id":"d","titleDe":"Diese Person ist Auszubildende in der Pflege.","textDe":""},{"id":"e","titleDe":"Diese Person hat einen Minijob und studiert nebenbei.","textDe":""},{"id":"f","titleDe":"Diese Person sucht noch nach einer passenden Stelle.","textDe":""}],"matchItems":[{"id":"h8-s1","textDe":"Murat","correctAd":"d"},{"id":"h8-s2","textDe":"Linda","correctAd":"b"},{"id":"h8-s3","textDe":"Sami","correctAd":"c"},{"id":"h8-s4","textDe":"Petra","correctAd":"a"},{"id":"h8-s5","textDe":"Khaled","correctAd":"e"}]}]}]'''));

